-- =====================================================================================
-- V1: initial schema.
--
-- Flyway runs every file in db/migration whose name starts with V<number>__ exactly once,
-- in version order, and records it in the "flyway_schema_history" table. NEVER edit a
-- migration that has already run somewhere: add V2__..., V3__... instead.
--
-- The SQL is written to work on BOTH PostgreSQL (prod) and H2 in PostgreSQL mode (dev/tests):
--   * "BIGINT GENERATED BY DEFAULT AS IDENTITY" is standard SQL supported by both.
--   * TIMESTAMP (without time zone) stores the office "wall-clock" time we use for bookings.
-- =====================================================================================

-- Accounts. "role" is either 'ADMIN' or 'USER' (Java enum Role stored as text).
CREATE TABLE users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          VARCHAR(100) NOT NULL,
    email         VARCHAR(255) NOT NULL UNIQUE,      -- login name; UNIQUE also creates an index
    password_hash VARCHAR(255) NOT NULL,             -- BCrypt hash, never the plain password
    role          VARCHAR(20)  NOT NULL DEFAULT 'USER',
    created_at    TIMESTAMP    NOT NULL
);

-- Bookable meeting rooms.
CREATE TABLE rooms (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100)  NOT NULL UNIQUE,       -- the database guarantees unique names
    location    VARCHAR(150)  NOT NULL,              -- e.g. "Floor 3, East wing"
    capacity    INTEGER       NOT NULL CHECK (capacity > 0),
    description VARCHAR(1000),
    active      BOOLEAN       NOT NULL DEFAULT TRUE, -- inactive rooms cannot be booked
    created_at  TIMESTAMP     NOT NULL
);

-- Amenities of a room ("Projector", "Whiteboard", ...).
-- A Set<String> in Java (@ElementCollection) becomes this separate "collection table":
-- one row per (room, amenity) pair. The composite primary key prevents duplicates,
-- which is exactly the semantics of a Set.
CREATE TABLE room_amenities (
    room_id BIGINT       NOT NULL REFERENCES rooms (id) ON DELETE CASCADE,
    amenity VARCHAR(50)  NOT NULL,
    PRIMARY KEY (room_id, amenity)
);

-- Reservations of a room by a user for a time range on a single day.
CREATE TABLE bookings (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    room_id     BIGINT        NOT NULL REFERENCES rooms (id),   -- no cascade: rooms with bookings
    user_id     BIGINT        NOT NULL REFERENCES users (id),   -- are deactivated, not deleted
    title       VARCHAR(150)  NOT NULL,
    description VARCHAR(1000),
    start_time  TIMESTAMP     NOT NULL,              -- office wall-clock time (no time zone)
    end_time    TIMESTAMP     NOT NULL,
    attendees   INTEGER       NOT NULL CHECK (attendees > 0),
    status      VARCHAR(20)   NOT NULL,              -- 'CONFIRMED' or 'CANCELLED'
    created_at  TIMESTAMP     NOT NULL,
    -- Last line of defence: even if application code had a bug, the DB rejects inverted ranges.
    CONSTRAINT chk_booking_time_order CHECK (end_time > start_time)
);

-- Indexes for the hottest queries:
--  * overlap check / room schedule:  WHERE room_id = ? AND status = ? AND start_time < ? AND end_time > ?
--  * "my bookings" / user overlap:   WHERE user_id = ? AND ...
--  * admin list filtered by day:     WHERE start_time >= ? AND start_time < ?
CREATE INDEX idx_bookings_room_time ON bookings (room_id, status, start_time, end_time);
CREATE INDEX idx_bookings_user_time ON bookings (user_id, status, start_time);
CREATE INDEX idx_bookings_start     ON bookings (start_time);
